from metrics import parse,value

def audit_migration(collect,policy):
    if not callable(collect)or type(policy)is not dict or set(policy)!={'asset_id','role','old_device','new_device'}:raise ValueError('approved mapping required')
    for key,item in policy.items():
        if type(item)is not str or not re.fullmatch(r'[A-Za-z0-9_.:-]{1,64}',item):raise ValueError('bounded nonempty mapping identifiers required')
    old,new=policy['old_device'],policy['new_device']
    if old==new:raise ValueError('different device names required')
