        samples=parse(observation['body'])
        if value(samples,'node_scrape_collector_success',{'collector':'netdev'})!=1:raise ValueError('netdev collection unavailable')
        counters={}
        for direction in ('receive','transmit'):
            item=value(samples,'node_network_'+direction+'_bytes_total',{'device':device})
            if item is None or not math.isfinite(item)or item<0 or not item.is_integer()or item>2**53:raise ValueError('exact nonnegative byte counter required')
            counters[direction]=int(item)
