        rows.append(dict(device=device,observed_at_ns=observation['observed_at_ns'],**counters))
    interval={}
    for direction in ('receive','transmit'):
        before,after=rows[1][direction],rows[2][direction]
        interval[direction]=dict(reset=after<before,delta_bytes=None if after<before else after-before)
    return dict(schema=1,asset_id=policy['asset_id'],role=policy['role'],observations=rows,historical_continuity=False,rename_delta_bytes=None,new_device_interval=interval)

