import json,re
LINE=re.compile(r'^([A-Za-z_:][A-Za-z0-9_:]*)(?:\{(.*)\})?\s+(\S+)(?:\s+[0-9]+)?$')
LABEL=re.compile(r'([A-Za-z_][A-Za-z0-9_]*)="((?:\\.|[^"\\])*)"')

def parse(body):
    result=[]
    for line in body.splitlines():
        if not line or line.startswith('#'):continue
        match=LINE.fullmatch(line)
        if match is None:raise ValueError('unsupported exposition line')
        name,raw,value=match.groups();labels={}
        if raw:
            position=0
            for item in LABEL.finditer(raw):
                if raw[position:item.start()].strip(', '):raise ValueError('invalid labels')
                key,encoded=item.groups()
                if key in labels:raise ValueError('duplicate label')
                labels[key]=json.loads('"'+encoded+'"');position=item.end()
            if raw[position:].strip(', '):raise ValueError('invalid label suffix')
        result.append((name,labels,float(value)))
    return result

def value(samples,name,labels=None):
    found=[v for n,l,v in samples if n==name and(labels is None or l==labels)]
    if len(found)>1:raise ValueError('ambiguous sample')
    return None if not found else found[0]

def key(name,labels):return name+json.dumps(labels,sort_keys=True,separators=(',',':'))

def self_metric(name):return name.startswith(('go_','process_','promhttp_','node_scrape_collector_'))or name=='node_exporter_build_info'

