"""Only a fresh nonroot node_exporter, private loopback port and textfile tree."""
import collections,json,os,pathlib,re,subprocess,tempfile,threading,time,urllib.error,urllib.parse,urllib.request

class Exporter:
    def __enter__(self):
        self.temp=tempfile.TemporaryDirectory(prefix='of-node-');self.root=pathlib.Path(self.temp.name);self.textdir=self.root/'textfile';self.textdir.mkdir();self.logs=collections.deque(maxlen=160);self.address=None;self.ready=threading.Event();self.proc=None;self.reader=None;self.parent=(os.getuid(),os.environ.get('HOME'),os.environ.get('PATH'))
        command=self.prepare(self.root,self.textdir)
        try:
            self.proc=subprocess.Popen(command,stdout=subprocess.DEVNULL,stderr=subprocess.PIPE)
            def drain():
                for raw in self.proc.stderr:
                    line=raw.decode(errors='replace').strip();self.logs.append(line)
                    try:row=json.loads(line)
                    except ValueError:continue
                    if row.get('msg')=='Listening on'and re.fullmatch(r'127\.0\.0\.1:[0-9]+',row.get('address','')):self.address=row['address'];self.ready.set()
            self.reader=threading.Thread(target=drain);self.reader.start()
            if not self.ready.wait(3)or self.proc.poll()is not None:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: owned exporter startup '+str(list(self.logs)))
            status=dict(line.split(':',1)for line in pathlib.Path('/proc',str(self.proc.pid),'status').read_text().splitlines()if ':'in line);self.uid=int(status['Uid'].split()[0])
            if self.uid!=1000:raise RuntimeError('NATIVE_ENVIRONMENT_ERROR: nonroot student exporter required')
            self.base='http://'+self.address;return self
        except BaseException:self.__exit__(None,None,None);raise
    def fetch(self,collectors=None):
        query=''if collectors is None else'?'+urllib.parse.urlencode([('collect[]',name)for name in collectors])
        url=self.base+'/metrics'+query
        try:
            with urllib.request.urlopen(url,timeout=2)as response:return {'status':response.status,'body':response.read().decode('utf-8')}
        except urllib.error.HTTPError as error:
            try:return {'status':error.code,'body':error.read().decode('utf-8')}
            finally:error.close()
    def __exit__(self,*args):
        try:
            if self.proc is not None:
                if self.proc.poll()is None:
                    self.proc.terminate()
                    try:self.proc.wait(timeout=3)
                    except subprocess.TimeoutExpired:self.proc.kill();self.proc.wait(timeout=2)
                if self.reader is not None:self.reader.join(timeout=2)
                self.proc.stderr.close()
        finally:
            self.temp.cleanup();assert self.parent==(os.getuid(),os.environ.get('HOME'),os.environ.get('PATH'))
            print('OWNED_EXPORTER_CLEANUP:'+json.dumps({'pid':None if self.proc is None else self.proc.pid,'reaped':self.proc is None or self.proc.poll()is not None,'exit_code':None if self.proc is None else self.proc.returncode,'directory_removed':not self.root.exists(),'parent_identity_environment_unchanged':True}),flush=True)

